package game.agent.eval;
import game.agent.llm.Json;import java.util.*;
/** Operator-supplied USD rates per million tokens, frozen in each batch. Never a billing claim. */
public final class EvaluationPricing {
 private EvaluationPricing(){}
 public static Map<String,Object> validate(Object value){if(value==null)return Collections.emptyMap();Map<String,Object> p=Json.asObject(value);if(!p.keySet().equals(new HashSet<>(Arrays.asList("version","currency","input","cachedInput","output","cacheWrite")))||!(p.get("version") instanceof String)||!((String)p.get("version")).matches("[a-zA-Z0-9_.:-]{1,80}")||!"USD".equals(p.get("currency")))throw new IllegalArgumentException("INVALID_PRICE_VERSION");for(String key:Arrays.asList("input","cachedInput","output","cacheWrite")){Object raw=p.get(key);if(!(raw instanceof Number)||!Double.isFinite(((Number)raw).doubleValue())||((Number)raw).doubleValue()<0||((Number)raw).doubleValue()>10000)throw new IllegalArgumentException("INVALID_PRICE");}return new LinkedHashMap<>(p);}
 public static Map<String,Object> cost(List<Map<String,Object>> calls,Map<String,Object> price){if(price.isEmpty())return Json.object("cost",null,"costReason","PRICE_NOT_CONFIGURED");double amount=0;for(Map<String,Object> call:calls){Map<String,Object> u=Json.asObject(call.get("usage"));for(String key:Arrays.asList("inputTokens","outputTokens","totalTokens","cachedInputTokens"))if(!u.containsKey(key))return Json.object("cost",null,"costReason","USAGE_INCOMPLETE");long in=n(u,"inputTokens"),out=n(u,"outputTokens"),cached=n(u,"cachedInputTokens"),written=u.containsKey("cacheWriteTokens")?n(u,"cacheWriteTokens"):0;if(cached>in||written>in-cached||n(u,"totalTokens")!=in+out)return Json.object("cost",null,"costReason","USAGE_INCONSISTENT");if(!u.containsKey("cacheWriteTokens")&&rate(price,"cacheWrite")!=rate(price,"input"))return Json.object("cost",null,"costReason","CACHE_WRITE_USAGE_UNKNOWN");amount+=((in-cached-written)*rate(price,"input")+cached*rate(price,"cachedInput")+written*rate(price,"cacheWrite")+out*rate(price,"output"))/1000000.0;}return Json.object("cost",calls.isEmpty()?null:amount,"costReason",calls.isEmpty()?"USAGE_INCOMPLETE":"CONFIGURED_ESTIMATE","priceVersion",price.get("version"),"currency","USD");}
 private static long n(Map<String,Object> m,String k){return EvaluationRandom.number(m.get(k));}private static double rate(Map<String,Object> m,String k){return((Number)m.get(k)).doubleValue();}
}
